<?php
require_once 'config.php';$uid=require_user();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['remove_wish'])){check_csrf();$id=(int)($_POST['id']??0);$q=$conn->prepare('DELETE FROM wishlist WHERE id=? AND user_id=?');$q->bind_param('ii',$id,$uid);$q->execute();redirect_to('wishlist.php');}
$q=$conn->prepare('SELECT w.*,p.product_type AS product_type FROM wishlist w LEFT JOIN products p ON p.id=w.pid WHERE w.user_id=? ORDER BY w.id DESC');$q->bind_param('i',$uid);$q->execute();$items=$q->get_result()->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="uk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Обране — flora.atelier</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/flor-v5.css"><link rel="stylesheet" href="css/flor-v6.css"><link rel="stylesheet" href="css/flor-v7.css"><link rel="stylesheet" href="css/flor-v8.css"><link rel="stylesheet" href="css/flor-v9.css"></head><body><?php require 'header.php';?><main class="page-shell"><div class="page-intro"><span class="eyebrow">ТВОЇ УЛЮБЛЕНЦІ</span><h1>Обрані <em>квіти</em></h1></div><div class="product-grid"><?php foreach($items as $r):?><article class="product-card"><a href="view_page.php?pid=<?=(int)$r['pid']?>" class="product-card-photo"><img src="<?=e(photo($r['image'], $r['product_type'] ?? ''))?>" alt="<?=e($r['name'])?>" onerror="this.onerror=null;this.src='assets/flower-placeholder.svg'"></a><div class="product-card-info"><h3><?=e($r['name'])?></h3><b><?=money($r['price'])?></b></div><form method="post"><?=csrf_input()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="link-underline" name="remove_wish" value="1">Прибрати з обраного</button></form></article><?php endforeach;?><?php if(!$items):?><div class="empty-state">Поки тут немає квітів. <a href="shop.php">Переглянути каталог ↗</a></div><?php endif;?></div></main><?php require 'footer.php';?></body></html>
